	('96f24d5f-c4c4-47f8-969b-eed8d88e4fd4', 'Lustra - Ivas', 'lustra', 'https://oscdtdlwdrwvjvteqcix.supabase.co/storage/v1/object/public/video%20and%20image/case_studies/Slide%2016_9%20-%20397szdac.png', 'Home Appliance - Premium Ceiling  Fan', '["https://images.unsplash.com/photo-1576091160550-2173dba999ef?w=1200&h=800&fit=crop", "https://images.unsplash.com/photo-1581093458791-9f3c3250a8b0?w=1200&h=800&fit=crop", "https://images.unsplash.com/photo-1579154204601-01588f351e67?w=1200&h=800&fit=crop"]', true, '2025-12-18 08:01:21.730692+00', '2025-12-18 08:01:21.730692+00', 'Lustra', 5, '#000000', 2024, 'Mystic Lustra blends decorative elegance with everyday performance.'),
	('b9f54b3b-58b7-487d-92ce-f94b61f76b7d11', 'Flora - Lucas TVS', 'flora', 'https://oscdtdlwdrwvjvteqcix.supabase.co/storage/v1/object/public/video%20and%20image/case_studies/1771478528022_ftbv8q.jpg', 'Kitchen Appliance - BLDC Mixer Grinder', NULL, true, NULL, NULL, 'FLORA', 7, '#464241', 2023, 'FLORA redefines the mixer grinder archetype by combining visual balance with functional stability.'),
	('b9f54b3b-58b7-487d-92ce-f94b61f76b7d1111111111111111111', 'Carbonyx - Confidencial', 'carbonyx', 'https://oscdtdlwdrwvjvteqcix.supabase.co/storage/v1/object/public/video%20and%20image/case_studies/Gemini_Generated_Image_cqqx3vcqqx3vcqqx%202.png', 'Consumer Electronic - Air Purifier', NULL, true, NULL, NULL, 'Carbonyx', 24, '#323232', 2026, 'A indoor air purifier which removes the carbon from the air and provides a clean and pollution free air.'),
	('b9f54b3b-58b7-487d-92ce-f94b61f76b7d1111111111111111', 'Walkie Talkie - Confidencial', 'emphor', 'https://oscdtdlwdrwvjvteqcix.supabase.co/storage/v1/object/public/video%20and%20image/case_studies/Slide%2016_9%20-%201278.png', 'Confidencial', NULL, true, NULL, NULL, 'emphor', 21, '#1A1A1A', 2026, ' A premium, elegant, and sophisticated walkie-talkie for modern professionals.'),
	('b9f54b3b-58b7-487d-92ce-f94b61f76b7d111111111111111111', 'Legacy - Bajaj Electricals', 'legacy', 'https://oscdtdlwdrwvjvteqcix.supabase.co/storage/v1/object/public/video%20and%20image/case_studies/Slide%2016_9%20-%201267.png', 'Consumer Electronic - Electric Iron', NULL, true, NULL, NULL, 'Legacy', 23, '#4D433E', 2024, 'A modular electric iron that blends premium design, ergonomic comfort, and reliable performance.'),
	('508bdd3a-22de-4d92-987a-059202fd3a60', 'Ellipse - Crompton', 'ellipse', 'https://oscdtdlwdrwvjvteqcix.supabase.co/storage/v1/object/public/video%20and%20image/case_studies/Slide%2016_9%20-%20371.png', 'Home Appliance -  Tower Fan', '["https://images.unsplash.com/photo-1563986768609-322da13575f3?w=1200&h=800&fit=crop", "https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=1200&h=800&fit=crop", "https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=1200&h=800&fit=crop"]', true, '2025-12-18 08:01:21.730692+00', '2025-12-18 08:01:21.730692+00', 'Ellipse', 3, '#0d0d1d', 2022, 'Ellipse brings calm aesthetics to everyday cooling.'),
	('173cb6a6-cd4a-4a0b-94e0-b2233851b58a', 'Enso - Confidencial', 'enso', 'https://oscdtdlwdrwvjvteqcix.supabase.co/storage/v1/object/public/video%20and%20image/case_studies/Slide%2016_9%20-%20346.png', 'Home Appliance - Air Purifier', '["https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=1200&h=800&fit=crop", "https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?w=1200&h=800&fit=crop", "https://images.unsplash.com/photo-1586023492125-27b2c045efd7?w=1200&h=800&fit=crop"]', true, '2025-12-18 07:56:41.867604+00', '2025-12-18 07:56:41.867604+00', 'Enso', 1, '#4a3738', 2025, 'ENSO brings calm aesthetics to everyday air purification.'),
