INSERT INTO "public"."lb_insights" ("id", "lesson", "category", "next_time", "happened", "project", "client", "hide_client", "seen_before", "tags", "photos", "links", "written_by", "status", "helpful", "helpful_by", "created_at", "updated_at", "from_case", "from_challenge") VALUES
	('60437122-7762-4317-976b-e6c319c90f10', 'Concept round with three directions converts better than five', 'proc', 'Present three developed directions with a clear recommendation rather than five sketches. Park the extras — bring them out only if all three are rejected.', 'Looked back at the last nine proposals. Five-direction presentations averaged two extra rounds before sign-off; three-direction presentations closed in one. More options read as less conviction.', 'vfd', 'dfcv', false, 'once', '{"concept presentation","client sign-off",proposal}', '[]', '[{"url": "https://www.iuovadesign.com/", "label": "Multiple"}]', 'Anirudha Masurkar', 'complete', 0, '{}', '2026-09-29 11:34:30.766708+00', '2026-09-29 11:37:54.04723+00', NULL, NULL),
	('55eea972-2b19-4892-8859-69246d4131cc', 'Toolmaker quoted P20 and delivered a softer equivalent — spec hardness, not grade name', 'mfg', 'Write the required hardness in HRC on the PO and require a material test certificate before T0. Grade names are not enforceable across local suppliers; a hardness number is.', 'Tool wore visibly at the parting line by 30,000 shots. Material certificate showed a local equivalent grade at lower hardness than the P20 the PO named.', 'Multiple', NULL, false, 'once', '{P20,"tool steel",hardness,"PO terms"}', '[]', '[]', 'Mandar Ambelkar', 'complete', 0, '{}', '2026-09-30 04:52:03.735753+00', '2026-09-30 04:52:03.735753+00', NULL, NULL);


