	('94bb114a-00cd-4c51-b2ea-a4a3a4b7ecea', 'Kanan Karwa', 'amitkarwa@gmail.com', '9820902886', 'Madovernuts.com', 'Madovernuts.com', 'Corporate Gifting', '0 - 10 Crores INR', 'Shared over email', '{"Product Design Services (Industrial Design)","Product Engineering Services","Prototyping Services","Manufacturing Services"}', '5 - 10 Lakhs INR (Upto 10000 USD)', '0 - 1 months', 'Pls refer email ', false, NULL, false, true, '100000', 'Refer email', 3, 'Google', '2026-07-18', '12:00 PM', NULL, '2026-07-17 08:00:31.278+00', '[{"id":"reply-tc-followup-1784691027121","to":"amitkarwa@gmail.com","cc":["support@iuova.in","crm@iuova.in","info@iuova.in"],"subject":"Techno - Commercial offer update follow up","body":"Hi Kanan Karwa,\n\nJust checking in to see if you had a chance to review our techno-commercial proposal.\n\nIf you have any questions, please reply to this email and we will be happy to help.\n\nRegards,\nIUOVA Team","sentAt":"2026-07-22T03:30:27.121Z","status":"sent","templateId":"tc-client-followup-1","messageIdHeader":"<d21542bd-1620-64c2-c20d-198d1baf5c78@iuova.in>","references":"<663dca78-0845-6d2a-bb45-683534113395@iuova.in> <a600a601-bb6b-4e10-12f7-e47725212484@iuova.in>","gmailThreadId":null,"direction":"outbound","source":"smtp"},{"id":"reply-1784352447413","to":"amitkarwa@gmail.com","cc":["info@iuova.in","crm@iuova.in, waseet@iuova.in, anirudha@iuova.in"],"subject":"Missed Meeting - Reschedule Request","body":"Dear Kanan Karwa,\n\nWe hope you''re doing well.\n\nIt seems we couldn''t connect for our scheduled online meeting today. We understand that unexpected commitments can arise.\n\nPlease let us know a convenient date and time for you, and we''ll be happy to reschedule the meeting. We look forward to connecting with you.\n\nBest regards,\nTeam IUOVA","sentAt":"2026-07-18T05:27:27.413Z","status":"sent","templateId":"meeting-missed","messageIdHeader":"<9c2bfd40-debe-88a0-4f9e-b3c8287c56ef@iuova.in>","references":"<12e5833a-19c4-6d81-ec93-3b025efd82be@iuova