}, {"title": "Render", "letter": "R", "output": "Frozen industrial design + CMF spec ready for engineering", "tagline": "Lock the visual + ergonomic identity", "duration": "3–4 weeks", "activities": "Refined ID, surface modelling, photoreal rendering, hand-feel mock-ups"}, {"title": "Generate", "letter": "G", "output": "Validated engineering prototype with passing test report", "tagline": "Build the engineering reality", "duration": "4–8 weeks", "activities": "CAD authoring, electronics architecture, prototype build, test cycles"}, {"title": "Engineer", "letter": "E", "output": "Production-ready CAD + tooling files + pilot run sign-off", "tagline": "Hand off to manufacturing", "duration": "4–6 weeks", "activities": "DFM, tooling design, vendor coordination, pilot run support, regulatory paperwork"}], "logos_enabled": true, "exec_objective": "To develop a market-ready industrial design and engineering platform for [Product Name] — combining differentiated form, validated function, and tooling-grade documentation that enables Q3 2026 manufacturing handover.", "project_status": "not viable", "sign_show_bank": false, "banking_enabled": true, "outcome_enabled": true, "recordCreatedAt": "2026-07-16T03:31:42.61+00:00", "sign_iuova_role": "Founder & Managing Director, IUOVA Design Company", "why_media_links": ["https://www.iuovadesign.com/media?video=f21526ed-ad59-41fb-92a7-72a5072ef891", "https://www.iuovadesign.com/media?video=e1524160-6dc7-40ff-acf5-bdf7dfaef0ab", "https://www.iuovadesign.com/media?video=fe8e5a11-b611-42a9-8375-8c072bd9453b", "https://www.iuovadesign.com/media?video=2094df21-a2dc-4eb7-b06e-09963c37036d"], "timeline_enabled": true, "comparison_matrix": {"06_survey": ["-", "-", "-"], "06_cmf_study": ["-", "-", "-"], "06_ecommerce": ["-", "-", "-"], "06_threshold": ["-", "-", "-"], "06_geographic": ["-", "-", "-"], "07_pkg_design": ["-", "-", "✓"], "07_pkg_artwork": ["-", "-", "✓"], "07_pkg_testing": ["-", "-", "✓"], "06_client_study": ["-", "-", "-"], "06_