	('3f702c3c-0fd5-47e0-95f2-a52299844e18', '918591126435', 'incoming', 'Hello', 'sent', NULL, NULL, '2026-06-15 06:47:44.197353+00', 'Anurag'),
	('053ec945-304c-40dd-8fe1-e6cfc17e973f', '918591126435', 'text', 'Hi Anurag! Welcome to IUOVA Design Company. 🚀 We are thrilled to connect with you.

